import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
try {
  const response = await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
  await page.waitForTimeout(1400);
  await page.locator('#start-button').click();
  await page.waitForTimeout(450);
  const started = await page.locator('#start-screen').evaluate(e => e.hidden);
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(850);
  await page.keyboard.up('KeyW');
  await page.waitForTimeout(350);
  const stance = await page.locator('#stance-label').textContent();
  await page.screenshot({ path: '/tmp/opencode/house-latest.jpg', type: 'jpeg', quality: 82 });
  console.log(JSON.stringify({status: response.status(), started, stance, errors, screenshot: '/tmp/opencode/house-latest.jpg'}));
} finally { await browser.close(); }

