import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.addInitScript(() => localStorage.setItem('house-within-save-v1', JSON.stringify({
  state: { day: 1, minutes: 432, totalMinutes: 432, flags: {}, doors: { front: false }, seen: [], history: [], weather: 'OVERCAST', eventAt: 517, lastEvent: -1000, seed: 1 },
  needs: { hunger: 18, thirst: 12, rest: 82, hygiene: 71, stress: 19, fear: 0, isolation: 23, suspicion: 9, stability: 81 },
  inventory: ['keys', 'phone', 'apple', 'tea'], rngSeed: 1, player: { x: 0, y: 0, z: 0.7, yaw: 0, pitch: 0 }, world: { fridgeOpen: false, lanternOn: true }
})));
const errors = [];
page.on('pageerror', e => errors.push(e.message));
try {
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' }); await page.waitForTimeout(1000);
  await page.locator('#continue-button').click(); await page.waitForTimeout(300);
  await page.keyboard.down('KeyW'); await page.waitForTimeout(6000); await page.keyboard.up('KeyW'); await page.waitForTimeout(200);
  const closed = { room: await page.locator('#room-name').textContent(), position: await page.evaluate(()=>window.__player.position.toArray()) };
  const near = { interact: await page.locator('#interact').isVisible(), label: await page.locator('#interact-label').textContent() };
  await page.keyboard.press('KeyE'); await page.waitForTimeout(1800);
  const opened = await page.evaluate(()=>({position:window.__player.position.toArray(),state:JSON.parse(localStorage.getItem('house-within-save-v1')||'{}').state.doors}));
  await page.keyboard.down('KeyW'); await page.waitForTimeout(7000); await page.keyboard.up('KeyW'); await page.waitForTimeout(500);
  const after = { room: await page.locator('#room-name').textContent(), position: await page.evaluate(()=>window.__player.position.toArray()), saved: await page.evaluate(()=>JSON.parse(localStorage.getItem('house-within-save-v1')||'{}').player) };
  await page.screenshot({path:'/tmp/opencode/door-latest.jpg',type:'jpeg',quality:82});
  console.log(JSON.stringify({closed,near,opened,after,errors}));
} finally { await browser.close(); }

