import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
const [room='living', out='/tmp/opencode/furniture-latest.jpg'] = process.argv.slice(2);
const positions = {
  living: { x: -2.65, z: 1.2, yaw: Math.PI / 2 },
  kitchen: { x: 5.2, z: 3.2, yaw: 0 },
  bedroom: { x: -2.4, z: 5.6, yaw: Math.PI / 2 },
};
const player = positions[room];
if (!player) throw new Error(`Unknown room: ${room}`);
const browser = await chromium.launch({ ...config.browser.launchOptions });
try {
 const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
 await page.addInitScript((player) => localStorage.setItem('house-within-save-v1', JSON.stringify({
  state: { day: 1, minutes: 432, totalMinutes: 432, flags: {}, doors: {}, seen: [], history: [], weather: 'OVERCAST', eventAt: 9999, lastEvent: -1000, seed: 1 },
  needs: { hunger: 18, thirst: 12, rest: 82, hygiene: 71, stress: 19, fear: 0, isolation: 23, suspicion: 9, stability: 81 },
  inventory: ['keys', 'phone', 'apple', 'tea'], rngSeed: 1, player: { ...player, y: 0, pitch: 0 }, world: { fridgeOpen: false, lanternOn: true }
 })), player);
 const errors=[]; page.on('pageerror', e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
 await page.waitForTimeout(1200);
 await page.locator('#continue-button').click();
 await page.waitForTimeout(1200);
 await page.screenshot({path:out,type:'jpeg',quality:84});
 console.log(JSON.stringify({room, title:await page.title(), roomLabel:await page.locator('#room-name').textContent(), errors, screenshot:out}));
} finally { await browser.close(); }

